<?php

declare(strict_types=1);

namespace Magento\Sitemap\Model;

// The real factory is generated by Magento at compile time and does not exist in a bare checkout.
if (!class_exists(SitemapItemInterfaceFactory::class, false)) {
    class SitemapItemInterfaceFactory
    {
        /**
         * @param array<string, mixed> $data
         */
        public function create(array $data = []): SitemapItemInterface
        {
            return new SitemapItem(
                (string) ($data['url'] ?? ''),
                (string) ($data['priority'] ?? ''),
                (string) ($data['changeFrequency'] ?? ''),
                isset($data['updatedAt']) ? (string) $data['updatedAt'] : null
            );
        }
    }
}
